// config/documents-page.ts
//
// Mock data and copy of the Documents screen. The official documents point at real files in /public/docs
// (generated by scripts/generate-docs.mjs); the ones the investor uploads are stored as metadata only.

import { BookOpen, FileCog, FileImage, FileText, Receipt, ScrollText, type LucideIcon } from "lucide-react";
import type { Tone } from "@/components/ui/KpiCard";
import type { IsoDate } from "@/lib/format";

export type DocCategory = "contratos" | "comprovantes" | "manuais" | "outros";

export type DocumentItem = {
  id: string;
  title: string;
  description: string;
  category: DocCategory;
  date: IsoDate;
  /** Upper-case file type shown next to the size: "PDF", "ZIP", "PNG"… */
  kind: string;
  sizeBytes: number;
  /** Public path of the file (official documents). Null for uploads, which keep metadata only. */
  file: string | null;
  /** Data URL of a small uploaded file, so it can be downloaded and previewed again. */
  dataUrl?: string | null;
  uploaded?: boolean;
  /** Name the browser saves the file as. */
  filename: string;
};

const kb = (n: number) => Math.round(n * 1024);
const mb = (n: number) => Math.round(n * 1024 * 1024);

